function renderExerciseList(){const list=state.exercises.filter(e=>(e.name+' '+e.group).toLowerCase().includes(search.toLowerCase()));$('#exercise-list').innerHTML=list.map(e=>`<article class="routine-card"><span class="badge neutral">${esc(e.group)}</span><h3 style="margin-top:17px">${esc(e.name)}</h3><p>${esc(e.notes||'Sin indicaciones adicionales.')}</p><div class="btns">${btn('Editar','edit-exercise','outline',`data-id="${esc(e.id)}"`)}${e.video?`<a class="btn outline" href="${esc(safeUrl(e.video))}" target="_blank" rel="noopener noreferrer">Ver video ↗</a>`:''}</div></article>`).join('')||empty('Sin resultados','Probá buscar otro ejercicio.');}
function safeUrl(v){try{const u=new URL(v);return ['https:','http:'].includes(u.protocol)?u.href:'#';}catch{return '#';}}

function noticeCards(list){return list.map(n=>`<article class="notice"><div class="row"><h3>${esc(n.title)}</h3><small>${dateLabel(n.date)}</small></div><p style="white-space:pre-wrap">${esc(n.body)}</p></article>`).join('');}
