function studentPicker(){return `<div class="field"><label for="student-select">Cambiar alumno (demo)</label><select id="student-select">${state.students.map(s=>`<option value="${esc(s.id)}" ${studentId===s.id?'selected':''}>${esc(s.name)}${s.status!=='active'?' · Inactivo':''}</option>`).join('')}</select></div>`;}
const measuresFor=sid=>state.measurements.filter(m=>m.studentId===sid).sort((a,b)=>b.date.localeCompare(a.date));
const numberLabel=n=>n===null||n===undefined?'—':Number(n).toLocaleString('es-AR',{maximumFractionDigits:1});
function currentWeekSessions(list){const now=new Date();const start=new Date(now.getFullYear(),now.getMonth(),now.getDate());start.setDate(start.getDate()-(start.getDay()+6)%7);return list.filter(x=>new Date(x.completedAt)>=start&&new Date(x.completedAt)<=now);}
function routineProgress(r,sid){const d=state.drafts[draftKey(sid,r.id)];return {done:r.exercises.filter((_,i)=>d?.done.includes(i)).length,started:!!d};}
function todayRoutine(routines){const day=new Date().toLocaleDateString('es-AR',{weekday:'long'});return routines.find(r=>r.days.some(d=>d.toLocaleLowerCase('es-AR')===day))||routines[0];}
function routineSummary(r,sid){const progress=routineProgress(r,sid);const weekday=new Date().toLocaleDateString('es-AR',{weekday:'long'});const isToday=r.days.some(d=>d.toLocaleLowerCase('es-AR')===weekday);return `<article class="routine-card student-routine-card"><div class="row"><span class="badge ${isToday?'':'neutral'}">${isToday?'Para hoy':'Tu entrenamiento'}</span><span class="note-text">${r.exercises.length} ejercicios</span></div><h2>${esc(r.name)}</h2><p>${esc(r.description||'Preparada por tu profesor.')}</p><div class="routine-day-chips">${r.days.map(d=>`<span>${esc(d)}</span>`).join('')}</div><details class="routine-preview"><summary>Ver ejercicios</summary><div>${r.exercises.map((e,i)=>`<div class="routine-preview-row"><span class="muted">${String(i+1).padStart(2,'0')}</span><div><h3>${esc(getExercise(e.exerciseId)?.name||'Ejercicio')}</h3><p>${e.sets} series · ${esc(e.reps)} · ${e.rest} s de descanso</p></div></div>`).join('')}</div></details>${progress.started?`<div class="row"><span class="note-text">Tu avance guardado</span><span class="note-text">${progress.done} / ${r.exercises.length}</span></div><div class="progress"><span style="width:${progress.done/r.exercises.length*100}%"></span></div>`:''}${btn((progress.started?'Continuar entrenamiento':'Comenzar entrenamiento')+' '+icon('arrow'),'start-workout','primary',`data-id="${esc(r.id)}"`)}</article>`;}
function renderStudent(){
 const s=selectedStudent();if(!s){main.innerHTML=heading('TU ENTRENAMIENTO','Todavía no hay alumnos','Cargá un alumno desde la vista Profesor para probar su experiencia.');return;}
 const sessions=sessionsFor(s.id);const routines=studentRoutines(s.id);
 if(page==='Avisos'){renderNotices(false);return;}
 if(s.status!=='active'){main.innerHTML=heading('TU ENTRENAMIENTO',esc(s.name),'Tu ficha está inactiva.')+`<section class="panel">${empty('Entrenamientos en pausa','Tu historial se conserva. El profesor puede reactivar tu ficha.')}</section>`;return;}
 if(page==='Inicio'){
  const r=todayRoutine(routines);const weekly=currentWeekSessions(sessions).length;
  main.innerHTML=heading('TU ESPACIO DE ENTRENAMIENTO',`Hola, ${esc(s.name.split(' ')[0])} <span class="greeting-hand" aria-hidden="true">👋</span>`,'Un paso más, a tu ritmo.')+`
  <section class="hero daily-hero student-daily-hero"><div><div class="eyebrow">TU FRASE DEL DÍA</div><h2>“${esc(phraseForDay('student'))}”</h2><p>Tu ritmo. Tu progreso.</p></div><div class="hero-art">${icon('activity')}</div></section>
  <div class="student-home-columns"><section class="panel today-workout"><div class="panel-heading"><h2>Tu entrenamiento</h2><span class="badge neutral">${r?'Asignado':'En preparación'}</span></div><div class="panel-content">${r?`<h2>${esc(r.name)}</h2><p class="note-text" style="margin-top:10px">${r.exercises.length} ejercicios · ${esc(r.days.join(' · '))}</p><div style="margin-top:20px">${btn('Ver mi rutina '+icon('arrow'),'student-routines','primary full')}</div>`:empty('Tu rutina está en camino','Tu profesor te avisará cuando esté lista.')}</div></section><section class="panel"><div class="panel-heading"><h2>Esta semana</h2></div><div class="panel-content"><div class="week-goal"><strong>${weekly}<span> / ${s.days}</span></strong><p>sesiones realizadas / objetivo</p></div><div class="progress"><span style="width:${Math.min(100,weekly/s.days*100)}%"></span></div><p class="note-text">${esc(s.goal)}</p>${btn('Ver mi progreso →','student-progress','ghost')}</div></section></div>
  <section class="panel" style="margin-top:23px"><div class="panel-heading"><h2>Tu recorrido</h2><span class="badge neutral">${sessions.length} sesiones</span></div><div class="panel-content">${sessionList(sessions)}</div></section>`;
 }else if(page==='Mi rutina'){
  if(detailId){const r=routines.find(x=>x.id===detailId);if(r)return renderWorkout(s,r);detailId=null;}
  main.innerHTML=heading('PLANIFICADO PARA VOS','Mi rutina','Entrenamientos preparados por '+esc(state.coach.name)+'.')+`<div class="cards student-routines">${routines.map(r=>routineSummary(r,s.id)).join('')}</div>${routines.length?'':empty('Tu rutina está en camino','El profesor todavía no te asignó entrenamientos.')}`;
 }else if(page==='Progreso')renderStudentProgress(s,sessions);
}
function renderStudentProgress(s,sessions){
 const measurements=measuresFor(s.id);const weight=measurements.find(m=>m.weight!==null);const height=measurements.find(m=>m.height!==null);
 const weeks=Array.from({length:4},(_,i)=>{const end=Date.now()-(3-i)*7*86400000;return sessions.filter(x=>{const d=new Date(x.completedAt).getTime();return d>end-7*86400000&&d<=end;}).length;});
 main.innerHTML=heading('UN RECORRIDO PROPIO','Mi progreso','Tus entrenamientos y registros personales.',btn(icon('plus')+' Registrar medidas','new-measurement'))+`
 <div class="grid-stats measurement-stats">${stat('Sesiones completadas',sessions.length,'Tu constancia, registrada','check')}${stat('Último peso',weight?numberLabel(weight.weight)+' kg':'—',weight?(weight.weight>300?'Revisar dato · '+dateLabel(weight.date):dateLabel(weight.date)):'Registro opcional','chart')}${stat('Última altura',height?numberLabel(height.height)+' cm':'—',height?dateLabel(height.date):'Registro opcional','activity')}</div>
 <section class="panel"><div class="panel-heading"><h2>Mis medidas</h2><span class="badge neutral">Registro manual</span></div>${measurements.length?`<div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Peso</th><th>Altura</th><th>Editar</th></tr></thead><tbody>${measurements.map(m=>`<tr><td>${dateLabel(m.date)}</td><td>${numberLabel(m.weight)}${m.weight!==null?' kg':''}${m.weight!==null&&(m.weight>300||m.weight<=0)?'<br><span class="badge pending">Revisar dato</span>':''}</td><td>${numberLabel(m.height)}${m.height!==null?' cm':''}${m.height!==null&&(m.height>300||m.height<=0)?'<br><span class="badge pending">Revisar dato</span>':''}</td><td>${btn('Editar','edit-measurement','ghost',`data-id="${esc(m.id)}"`)}</td></tr>`).join('')}</tbody></table></div>`:empty('Tu progreso va más allá de un número','Si querés, registrá peso y altura para consultar su evolución.')}<div class="panel-content"><p class="note-text">Estos datos son opcionales. Se guardan en este navegador; esta versión no los comparte con el profesor.</p></div></section>
 <div class="two-col" style="margin-top:23px"><section class="panel"><div class="panel-heading"><h2>Sesiones por semana</h2></div><div class="panel-content"><div class="trend-bars" role="img" aria-label="Sesiones en las últimas cuatro semanas: ${weeks.join(', ')}">${weeks.map((n,i)=>`<div class="trend-column"><span>${n}</span><div class="bar" style="height:${Math.max(3,n/Math.max(1,...weeks)*100)}px"></div><span>${i===3?'Actual':'Hace '+(3-i)+' sem.'}</span></div>`).join('')}</div></div></section><section class="panel"><div class="panel-heading"><h2>Historial de entrenamientos</h2></div><div class="panel-content">${sessionList(sessions,true)}</div></section></div>`;
}
